#include "string.h"
size_t strlen(const char *сатр_иттилоот) { const char *자료위치 = сатр_иттилоот; while (*자료위치) 자료위치++; return 자료위치 - сатр_иттилоот; }
int memcmp(const void *첫째값, const void *둘째값, size_t 개수) { const unsigned char *координатаи_х = 첫째값, *세로좌표 = 둘째값; while (개수--) { if (*координатаи_х != *세로좌표) return (int)*координатаи_х - *세로좌표; координатаи_х++; 세로좌표++; } return 0; }
void *memmove(void *ҷои_таъинот_иттилоот, const void *сатр_иттилоот, size_t 개수) { unsigned char *координатаи_х = ҷои_таъинот_иттилоот; const unsigned char *세로좌표 = сатр_иттилоот; if (координатаи_х < 세로좌표) { for (size_t 순번 = 0; 순번 < 개수; 순번++) координатаи_х[순번] = 세로좌표[순번]; } else { while (개수) { 개수--; координатаи_х[개수] = 세로좌표[개수]; } } return ҷои_таъинот_иттилоот; }
int strncmp(const char *첫째값, const char *둘째값, size_t 개수) { while (개수--) { unsigned char координатаи_х = *첫째값++, 세로좌표 = *둘째값++; if (координатаи_х != 세로좌표) return (int)координатаи_х-세로좌표; if (!координатаи_х) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *сатр_иттилоот, char **анҷом_додан_Интиқолшавӣ, int Пасзамина_қимат) {
    const char *Оғоз_Интиқолшавӣ = сатр_иттилоот; unsigned long қимат = 0; int рамзгузорӣ_қимат = 1, 하나라도 = 0;
    while (*сатр_иттилоот == ' ' || (*сатр_иттилоот >= 9 && *сатр_иттилоот <= 13)) сатр_иттилоот++;
    if (*сатр_иттилоот == '-' || *сатр_иттилоот == '+') { if (*сатр_иттилоот == '-') рамзгузорӣ_қимат = -1; сатр_иттилоот++; }
    if (Пасзамина_қимат == 0) Пасзамина_қимат = 10;
    while (*сатр_иттилоот >= '0' && *сатр_иттилоот <= '9' && *сатр_иттилоот - '0' < Пасзамина_қимат) {
        unsigned рақам_қимат = *сатр_иттилоот++ - '0'; 하나라도 = 1;
        if (қимат > (0x7ffffffffffffffful - рақам_қимат) / (unsigned)Пасзамина_қимат) қимат = 0x7ffffffffffffffful;
        else қимат = қимат * Пасзамина_қимат + рақам_қимат;
    }
    if (анҷом_додан_Интиқолшавӣ) *анҷом_додан_Интиқолшавӣ = (char *)(하나라도 ? сатр_иттилоот : Оғоз_Интиқолшавӣ); return рамзгузорӣ_қимат > 0 ? (long)қимат : -(long)қимат;
}
int atoi(const char *сатр_иттилоот) { return (int)strtol(сатр_иттилоот, 0, 10); }
